-- Cosmetics -- wings and auras -- drawn on a player as attached effects. The 8.60 outfit
-- packet carries neither, so each kind rides its own extended opcode; the server half is
-- OTSERV data/cosmetics/cosmetics.lua.
-- Server -> client, '|'-separated: "set|<creatureId>|<id>", "clear|<creatureId>", "reset"
-- ahead of a full list, and "owned|<json>" (what the outfit window may offer).
-- Client -> server: "list" and "choose|<id>" (0 = none).
-- WINGS_LIST and AURAS_LIST are generated by OTSERV tools/import_wings.ps1 and
-- tools/import_auras.ps1.

-- `effectBase` + id is the attached effect a kind's entry is registered as, clear of every
-- id game_attachedeffects registers itself and of each other (ids run to 299).
local KINDS = {
    wings = {
        opcode = 92,
        effectBase = 3000,
        list = function() return WINGS_LIST end,
        -- A wing is an outfit sprite in Tibia.dat. `offsets` (N, E, S, W) is how far this art
        -- sits from where every other wing's does, measured by the generator. In front facing
        -- north (over the back) and west, behind the body facing south and east.
        register = function(manager, effectId, entry)
            local o = entry.offsets
            manager.register(effectId, entry.name, entry.lookType, ThingCategoryCreature, {
                speed = entry.speed,
                followOwner = true,
                dirOffset = {
                    [North] = { o[1][1], o[1][2], true },
                    [East] = { o[2][1], o[2][2], false },
                    [South] = { o[3][1], o[3][2], false },
                    [West] = { o[4][1], o[4][2], true }
                }
            })
        end
    },
    auras = {
        opcode = 93,
        effectBase = 3500,
        list = function() return AURAS_LIST end,
        -- An aura goes around the player, so it is two outfits in Tibia.dat, cut by the
        -- generator at the middle of the art: `back`, the far half, drawn behind the body, and
        -- `front`, the near half, over it. The aura's own effect draws nothing; it carries the
        -- two halves (4000 + id and 4400 + id) as child effects. A child draws in its own pass
        -- only when the parent has no picture, which is why the parent is empty. A child is
        -- never turned with the player, so each half has the one direction.
        register = function(manager, effectId, entry, id)
            local backId, frontId = 4000 + id, 4400 + id
            for _, half in ipairs({ { backId, entry.back, false }, { frontId, entry.front, true } }) do
                manager.register(half[1], entry.name, half[2], ThingCategoryCreature, {
                    speed = entry.speed,
                    offset = { 0, 0, half[3] }
                })
            end
            manager.register(effectId, entry.name, 0, 0, {
                followOwner = true,
                onAttach = function(effect)
                    effect:attachEffect(g_attachedEffects.getById(backId))
                    effect:attachEffect(g_attachedEffects.getById(frontId))
                end
            })
        end
    }
}

-- Kept by creature id rather than only on the Creature, because a creature leaving view and
-- coming back can arrive as a fresh object wearing nothing.
local worn = {}
local ownedCallbacks = {}

function effectId(kind, id)
    return KINDS[kind].effectBase + id
end

-- The entry id an attached effect id stands for, 0 for none ("None", nil, another kind's).
function entryId(kind, effect)
    local id = tonumber(effect)
    local k = KINDS[kind]
    if id and k.list()[id - k.effectBase] then
        return id - k.effectBase
    end
    return 0
end

function getName(kind, id)
    local entry = KINDS[kind].list()[id]
    return entry and entry.name or 'None'
end

local function registerEffects()
    local manager = modules.game_attachedeffects.AttachedEffectManager
    for _, k in pairs(KINDS) do
        for id, entry in pairs(k.list()) do
            k.register(manager, k.effectBase + id, entry, id)
        end
    end
end

local function apply(creature)
    if not creature:isPlayer() then
        return
    end
    for kind, k in pairs(KINDS) do
        local wearing = worn[kind][creature:getId()]
        for id in pairs(k.list()) do
            if id ~= wearing and creature:getAttachedEffectById(k.effectBase + id) then
                creature:detachEffectById(k.effectBase + id)
            end
        end
        if wearing and not creature:getAttachedEffectById(k.effectBase + wearing) then
            local effect = g_attachedEffects.getById(k.effectBase + wearing)
            if effect then
                creature:attachEffect(effect)
            end
        end
    end
end

local function applyById(id)
    local creature = g_map.getCreatureById(id)
    if creature then
        apply(creature)
    end
end

local function send(kind, message)
    local protocolGame = g_game.isOnline() and g_game.getProtocolGame()
    if protocolGame then
        protocolGame:sendExtendedOpcode(KINDS[kind].opcode, message)
    end
end

local function onOpcode(kind, buffer)
    if buffer:sub(1, 6) == 'owned|' then
        local ok, data = pcall(json.decode, buffer:sub(7))
        if not ok or type(data) ~= 'table' then
            g_logger.error('[game_cosmetics] bad ' .. kind .. ' owned payload: ' .. tostring(data))
            return
        end
        if ownedCallbacks[kind] then
            ownedCallbacks[kind](data)
        end
        return
    end

    local verb, id, entry = buffer:match('^(%a+)|?(%d*)|?(%d*)$')
    id, entry = tonumber(id), tonumber(entry)
    if verb == 'reset' then
        local old = worn[kind]
        worn[kind] = {}
        for oldId in pairs(old) do
            applyById(oldId)
        end
    elseif verb == 'set' and id and entry and KINDS[kind].list()[entry] then
        worn[kind][id] = entry
        applyById(id)
    elseif verb == 'clear' and id then
        worn[kind][id] = nil
        applyById(id)
    end
end

-- The outfit window's half: ask which entries of a kind this player owns, and pick one. The
-- callback gets { current = <id>, owned = { <id>... } } after a "list" and after every "choose".
function requestOwned(kind, callback)
    ownedCallbacks[kind] = callback
    send(kind, 'list')
end

function stopOwned(kind)
    ownedCallbacks[kind] = nil
end

function choose(kind, id)
    send(kind, string.format('choose|%d', id))
end

local function onGameEnd()
    for kind in pairs(KINDS) do
        worn[kind] = {}
    end
    ownedCallbacks = {}
end

function init()
    onGameEnd()
    registerEffects()
    for kind, k in pairs(KINDS) do
        ProtocolGame.registerExtendedOpcode(k.opcode, function(protocol, opcode, buffer)
            onOpcode(kind, buffer)
        end)
    end
    connect(Creature, { onAppear = apply })
    connect(g_game, { onGameEnd = onGameEnd })
end

function terminate()
    for _, k in pairs(KINDS) do
        ProtocolGame.unregisterExtendedOpcode(k.opcode)
    end
    disconnect(Creature, { onAppear = apply })
    disconnect(g_game, { onGameEnd = onGameEnd })
end
